sys_ui_script.script:
/* PTAG Hub theme boot (B147, 2026-09-29) - JS include of the PTAG Engage Dark theme.
   Runs in <head>, before the body is parsed, so html[data-pt-theme] is right on the FIRST
   frame: no flash of the wrong theme.
   Truth = the viewer's user preference ptag.hub.theme ('dark' | 'light', default dark).
   Fast path: a per-user cache of it (localStorage 'ptag.hub.theme.<user sys_id>').
   First visit on a device (no cache): ONE synchronous read of the viewer's own preference
   row (Table API, own-row ACL), then cached. ptag_global confirms the server value before
   the boot splash lifts; the header toggle updates both. /ptag only - never the embed pages
   or the sign-in page. Any failure falls back to dark (today's look). */
(function () {
  try {
    if (!/^\/ptag\/?$/.test(window.location.pathname)) { return; }
    if (/[?&]id=(ptag_embed|ptag_login)/.test(window.location.search || '')) { return; }
    var N = window.NOW || {};
    var uid = String(N.user_id || '');
    var t = '';
    if (uid && N.user_name && N.user_name !== 'guest') {
      var key = 'ptag.hub.theme.' + uid;
      try { t = window.localStorage.getItem(key) || ''; } catch (e1) { t = ''; }
      if (t !== 'light' && t !== 'dark') {
        t = '';
        try {
          var x = new XMLHttpRequest();
          x.open('GET', '/api/now/table/sys_user_preference?sysparm_fields=value&sysparm_limit=1&sysparm_query=' +
                 encodeURIComponent('user=' + uid + '^name=ptag.hub.theme'), false);
          x.setRequestHeader('Accept', 'application/json');
          if (window.g_ck) { x.setRequestHeader('X-UserToken', window.g_ck); }
          x.send(null);
          if (x.status === 200) {
            var r = (JSON.parse(x.responseText) || {}).result || [];
            t = (r[0] && r[0].value === 'light') ? 'light' : 'dark';
            try { window.localStorage.setItem(key, t); } catch (e2) {}
          }
        } catch (e3) { t = ''; }
      }
    }
    document.documentElement.setAttribute('data-pt-theme', t === 'light' ? 'light' : 'dark');
  } catch (e) {}
})();
